(4106430, 587989, 82431, '<td valign="top">Great DOP, meets the challenge with humour. Love it!</td>', 'Great DOP, meets the challenge with humour. Love it!', '2007-09-21 06:10:32.000000', NULL, 1),
(4106431, 588959, 83773, '<td valign="top">nice, you seem to have captured quite a few concepts in one photo- not obvious at first, and i''m not sure whether its intentional or serendipitous, but i like it never the less... high marks.</td>', 'nice, you seem to have captured quite a few concepts in one photo- not obvious at first, and i''m not sure whether its intentional or serendipitous, but i like it never the less... high marks.', '2007-09-21 06:12:03.000000', NULL, 1),
(4106432, 587315, 82431, '<td valign="top">A few too many colours going on in this shot, and the framing is lacking... more green space around the main subject would improve it.  The subject itself I like though.</td>', 'A few too many colours going on in this shot, and the framing is lacking... more green space around the main subject would improve it.  The subject itself I like though.', '2007-09-21 06:12:08.000000', NULL, 1),
(4106433, 586902, 83773, '<td valign="top">oooh, its like guess the currencies! i  like it, nice idea!</td>', 'oooh, its like guess the currencies! i  like it, nice idea!', '2007-09-21 06:13:21.000000', NULL, 1),
(4106434, 588953, 82431, '<td valign="top">Great bit of street photography - I''m convinced we''re going to see a ''homeless'' subject in the top three of this challenge, this could well be it.</td>', 'Great bit of street photography - I''m convinced we''re going to see a ''homeless'' subject in the top three of this challenge, this could well be it.', '2007-09-21 06:13:32.000000', NULL, 1),
