(4106437, 588081, 82431, '<td valign="top">DOF a little too harsh for my liking, but composition and colours are great.</td>', 'DOF a little too harsh for my liking, but composition and colours are great.', '2007-09-21 06:16:16.000000', NULL, 1),
(4106438, 588915, 82431, '<td valign="top">Stretching the challenge perhaps but I don''t care, this is a gorgeous landscape!!</td>', 'Stretching the challenge perhaps but I don''t care, this is a gorgeous landscape!!', '2007-09-21 06:18:46.000000', NULL, 1),
(4106439, 588763, 82431, '<td valign="top">Gorgeous, DOF is spot on, love the colours, lighting and composition</td>', 'Gorgeous, DOF is spot on, love the colours, lighting and composition', '2007-09-21 06:19:57.000000', NULL, 1),
(4106440, 588298, 82431, '<td valign="top">Great shot, only let down by the foremost ring being OOF</td>', 'Great shot, only let down by the foremost ring being OOF', '2007-09-21 06:20:42.000000', NULL, 1),
(4106441, 588492, 82431, '<td valign="top">This put a smile on my face, as I''m sure it will many others'' - great composition and colours. Was the black vest on your model a deliberate choice to match the lens?</td>', 'This put a smile on my face, as I''m sure it will many others'' - great composition and colours. Was the black vest on your model a deliberate choice to match the lens?', '2007-09-21 06:22:42.000000', NULL, 1),
(4106442, 588766, 82431, '<td valign="top">Wonderful shot, great composition, might have benefited from the slightest of crops to the top to match the bottom edge. Otherwise it''s delightful - hope to see it do well</td>', 'Wonderful shot, great composition, might have benefited from the slightest of crops to the top to match the bottom edge. Otherwise it''s delightful - hope to see it do well', '2007-09-21 06:23:46.000000', NULL, 1),
(4106444, 588149, 82431, '<td valign="top">Nice family snapshot, would have been far better shot outside with a good scenic background. DMC in my opinion.</td>', 'Nice family snapshot, would have been far better shot outside with a good scenic background. DMC in my opinion.', '2007-09-21 06:26:18.000000', NULL, 1),
(4106445, 588479, 82431, '<td valign="top">My 1st 10 so far.  Adore this.</td>', 'My 1st 10 so far.  Adore this.', '2007-09-21 06:26:51.000000', NULL, 1),
(4106446, 588501, 82431, '<td valign="top">AS the image loaded I was a little disappointed, "another landscape" I thought.  But actually it works wonderfully, composition could be better but I''m going to score highly because I love the thought behind it.</td>', 'AS the image loaded I was a little disappointed, "another landscape" I thought.  But actually it works wonderfully, composition could be better but I''m going to score highly because I love the thought behind it.', '2007-09-21 06:28:02.000000', NULL, 1),
(4106449, 588818, 82431, '<td valign="top">Gorgeous shot, colours are perfect.  Highlight and pose on the magazine is a bit overstated, something with a more candid feel would have worked better.  Nontheless I expect to see this do well, a 9 from me.</td>', 'Gorgeous shot, colours are perfect.  Highlight and pose on the magazine is a bit overstated, something with a more candid feel would have worked better.  Nontheless I expect to see this do well, a 9 from me.', '2007-09-21 06:29:46.000000', NULL, 1),
(4106450, 588563, 82431, '<td valign="top">A little more time in composing the subject would have gotten a 10.  It would have been much nicer to see the pears fill the frame seamlessly with no ground or leaves interrupting the great yellow and brown tones of the rotten fruit.</td>', 'A little more time in composing the subject would have gotten a 10.  It would have been much nicer to see the pears fill the frame seamlessly with no ground or leaves interrupting the great yellow and brown tones of the rotten fruit.', '2007-09-21 06:32:20.000000', NULL, 1),
(4106451, 586451, 82431, '<td valign="top">I didn''t want to like this shot, I was expecting too many of them, but I can''t help but love it.  The colour, lighting and texture is spot on, a worthy 10</td>', 'I didn''t want to like this shot, I was expecting too many of them, but I can''t help but love it.  The colour, lighting and texture is spot on, a worthy 10', '2007-09-21 06:34:08.000000', NULL, 1),
(4106506, 588408, 48086, '<td valign="top">something went wrong with the colors, too much shadow highlight?</td>', 'something went wrong with the colors, too much shadow highlight?', '2007-09-21 08:31:06.000000', NULL, 1),
(4106518, 588956, 48086, '<td valign="top">Too bad about the lighting, a bit too sharp</td>', 'Too bad about the lighting, a bit too sharp', '2007-09-21 08:39:33.000000', NULL, 1),
