(4106521, 586902, 48086, '<td valign="top">Simpel but effective, improved lighting could make this a better picture, too flat</td>', 'Simpel but effective, improved lighting could make this a better picture, too flat', '2007-09-21 08:41:05.000000', NULL, 1),
