(4107191, 587653, 83375, '<td valign="top">Not so sure about the challenge requirements...or just how nutritious a sunflower seed is.</td>', 'Not so sure about the challenge requirements...or just how nutritious a sunflower seed is.', '2007-09-21 14:45:25.000000', NULL, 1),
(4107194, 587989, 83375, '<td valign="top">Finally, an idea that made me laugh.</td>', 'Finally, an idea that made me laugh.', '2007-09-21 14:46:50.000000', NULL, 1),
(4107198, 588482, 83375, '<td valign="top">DNMC, plus a bit soft/hazy looking.</td>', 'DNMC, plus a bit soft/hazy looking.', '2007-09-21 14:48:01.000000', NULL, 1),
(4107206, 588240, 83375, '<td valign="top">soft, not well lit and DNMC</td>', 'soft, not well lit and DNMC', '2007-09-21 14:50:09.000000', NULL, 1),
(4107209, 585858, 83375, '<td valign="top">love the lights in this shot.</td>', 'love the lights in this shot.', '2007-09-21 14:51:01.000000', NULL, 1),
(4107263, 586428, 62187, '<td valign="top">It''s a very good photograph for sure. Personally, I think it could use a touch more contrast. As far as meeting the challenge: I totally understand where you are coming from. I may be wrong but I don''t think others will think of it as ''Wealth'' as much as some of the other photos or in the mainstream idea. I think they may think of it as a ''shoehorn''. However, I like it, this site is about photography mostly. I''ll go with a strong 7.</td>', 'It''s a very good photograph for sure. Personally, I think it could use a touch more contrast. As far as meeting the challenge: I totally understand where you are coming from. I may be wrong but I don''t think others will think of it as ''Wealth'' as much as some of the other photos or in the mainstream idea. I think they may think of it as a ''shoehorn''. However, I like it, this site is about photography mostly. I''ll go with a strong 7.', '2007-09-21 15:20:22.000000', NULL, 1),
(4107270, 587547, 62187, '<td valign="top">The church has too much money - how ''bout them starving people? That''s where they should be spendin'' their money! Just kidding, it''s their money, they can do what they want with it - the photo? Very nice. I''d like to see a little wider view of the whole dome but, this is good.</td>', 'The church has too much money - how ''bout them starving people? That''s where they should be spendin'' their money! Just kidding, it''s their money, they can do what they want with it - the photo? Very nice. I''d like to see a little wider view of the whole dome but, this is good.', '2007-09-21 15:23:53.000000', NULL, 1),
(4107273, 588081, 62187, '<td valign="top">Since I can''t give you $20, I''ll go with $10.</td>', 'Since I can''t give you $20, I''ll go with $10.', '2007-09-21 15:25:08.000000', NULL, 1),
(4107275, 588482, 62187, '<td valign="top">It''s kinda blurry to me and lacking color - kinda drab. The positioning of the lighthouse and mast (?) flow nicely with the sky.</td>', 'It''s kinda blurry to me and lacking color - kinda drab. The positioning of the lighthouse and mast (?) flow nicely with the sky.', '2007-09-21 15:28:26.000000', NULL, 1),
(4107277, 588950, 62187, '<td valign="top">The colors are a little overpowering to me but the composition is great!</td>', 'The colors are a little overpowering to me but the composition is great!', '2007-09-21 15:29:00.000000', NULL, 1),
(4107279, 588004, 62187, '<td valign="top">I like where your going with the processing but it''s a little overdone for me. Love the idea and choice of background.</td>', 'I like where your going with the processing but it''s a little overdone for me. Love the idea and choice of background.', '2007-09-21 15:30:51.000000', NULL, 1),
(4107292, 588915, 62187, '<td valign="top">I would have to agree with you on the title and idea! The photo to me has a lot of grain in it and I think a better composition might have been to place the taller trees and rock more to the right - a little less centered. It looks like a beautiful place!</td>', 'I would have to agree with you on the title and idea! The photo to me has a lot of grain in it and I think a better composition might have been to place the taller trees and rock more to the right - a little less centered. It looks like a beautiful place!', '2007-09-21 15:35:34.000000', NULL, 1),
(4107296, 588678, 62187, '<td valign="top">Wow - really!?!?!?! Where is this? It''s a great picture - the composition is perfect as well as the conversion to B&amp;W. I know the Titanic spared no expense in it''s building - but, it''s just not quite what I thought the challenge was all about. However, I think a 9 should do nicely?</td>', 'Wow - really!?!?!?! Where is this? It''s a great picture - the composition is perfect as well as the conversion to B&W. I know the Titanic spared no expense in it''s building - but, it''s just not quite what I thought the challenge was all about. However, I think a 9 should do nicely?', '2007-09-21 15:37:55.000000', NULL, 1),
(4107300, 588756, 62187, '<td valign="top">Alright, I''ll go for it. It''s kinda taking the challenge in the opposite direction but I like all the angles and contrasting colors. 8</td>', 'Alright, I''ll go for it. It''s kinda taking the challenge in the opposite direction but I like all the angles and contrasting colors. 8', '2007-09-21 15:39:36.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(4107307, 587653, 62187, '<td valign="top">Well, to me, it''s kinda shoehornish: the title is kinda what makes it not DNMC. However, it''s a nice photo, the composition is perfect. I''ll go with a 7.</td>', 'Well, to me, it''s kinda shoehornish: the title is kinda what makes it not DNMC. However, it''s a nice photo, the composition is perfect. I''ll go with a 7.', '2007-09-21 15:41:31.000000', NULL, 1),
(4107316, 585858, 62187, '<td valign="top">Well, I want to give it a 10 because it''s such a perfect photo. But for the challenge, I''m not getting these ''Religious'' type entries as ''Wealth''. It''s kinda pushing the envelope for me but I''ll still go with a 9.</td>', 'Well, I want to give it a 10 because it''s such a perfect photo. But for the challenge, I''m not getting these ''Religious'' type entries as ''Wealth''. It''s kinda pushing the envelope for me but I''ll still go with a 9.', '2007-09-21 15:45:12.000000', NULL, 1),
(4107322, 588492, 62187, '<td valign="top">This style of cropping seems to be getting more popular - with the dead-space on the ''wrong'' side of the subject. I like it. You have great lighting and I''m sure this will do well with the DPC''ers. 10</td>', 'This style of cropping seems to be getting more popular - with the dead-space on the ''wrong'' side of the subject. I like it. You have great lighting and I''m sure this will do well with the DPC''ers. 10', '2007-09-21 15:47:19.000000', NULL, 1),
(4107324, 588967, 62187, '<td valign="top">There we go! Very nice. Everything is perfect and it deserves a 10.</td>', 'There we go! Very nice. Everything is perfect and it deserves a 10.', '2007-09-21 15:48:04.000000', NULL, 1),
(4107326, 588780, 62187, '<td valign="top">On the fringe of shoehorn to me but who cares. I love the edit! 9</td>', 'On the fringe of shoehorn to me but who cares. I love the edit! 9', '2007-09-21 15:49:22.000000', NULL, 1),
(4107335, 586856, 62187, '<td valign="top">Really? Lovers? That''s kind of disgusting...for lack of better word. I certainly get your point but think a better title would have been more tasteful - something along the line of ''friends or friendship maybe? Anyway, the photo is good - maybe just a tad more contrast?</td>', 'Really? Lovers? That''s kind of disgusting...for lack of better word. I certainly get your point but think a better title would have been more tasteful - something along the line of ''friends or friendship maybe? Anyway, the photo is good - maybe just a tad more contrast?', '2007-09-21 15:53:06.000000', NULL, 1),
(4107337, 586827, 62187, '<td valign="top">Kinda looks like an oil painting to me. I think a less centered crop would have greatly improved the overall score. I''ll go with a 7.</td>', 'Kinda looks like an oil painting to me. I think a less centered crop would have greatly improved the overall score. I''ll go with a 7.', '2007-09-21 15:54:02.000000', NULL, 1),
